namespace ViceSharp.Core.Vic20;

/// <summary>
/// VIC-20 Ultimem (VICE ultimem.c) MVP: register file at $9C00+, banked BLK windows.
/// </summary>
public sealed class UltimemCartridge : IAddressSpace
{
    public const int MaxImageSize = 0x1000000; // up to 16MB in VICE; we accept up to 1MB for MVP
    public const int DefaultImageSize = 0x100000; // 1MB

    private readonly byte[] _image;
    private readonly byte[] _registers = new byte[16];
    private bool _imageDirty;

    public UltimemCartridge(ReadOnlySpan<byte> image)
    {
        var size = Math.Max(DefaultImageSize, image.Length);
        if (size > MaxImageSize)
            throw new ArgumentException("Ultimem image too large.", nameof(image));
        _image = new byte[size];
        if (!image.IsEmpty)
            image[..Math.Min(image.Length, size)].CopyTo(_image);
        Id = new DeviceId(0x0C11);
        PowerUp();
    }

    public DeviceId Id { get; }
    public string Name => "Ultimem";
    public bool ImageDirty => _imageDirty;
    public bool WriteBack { get; set; }

    public void PowerUp()
    {
        Array.Fill(_registers, (byte)0xFF);
        // Enabled BLK5 ROM-ish default bank 0
        _registers[0] = 0x00;
        _registers[1] = 0x00;
        _registers[2] = 0x00; // cfg
    }

    public void Reset() => PowerUp();

    public void ApplyConfigPreset(string presetId)
    {
        switch (presetId.Trim().ToLowerInvariant())
        {
            case "default":
            case "start":
                PowerUp();
                break;
            case "blk5-rom":
                PowerUp();
                _registers[2] = 0x03; // BLK5 ROM enabled (2 bits * block)
                break;
            case "ram-all":
                PowerUp();
                _registers[2] = 0xFF;
                break;
            default:
                throw new ArgumentException($"Unknown Ultimem preset '{presetId}'.", nameof(presetId));
        }
    }

    public bool HandlesAddress(ushort address)
        => address is (>= 0x9C00 and <= 0x9FFF)
            or (>= 0x2000 and <= 0x3FFF)
            or (>= 0x4000 and <= 0x7FFF)
            or (>= 0xA000 and <= 0xBFFF)
            or (>= 0x0400 and <= 0x0FFF);

    public byte Read(ushort address)
    {
        if (address is >= 0x9C00 and <= 0x9FFF)
            return _registers[address & 0x0F];
        if (TryMap(address, out var offset))
            return _image[offset];
        return 0xFF;
    }

    public byte Peek(ushort address) => Read(address);

    public void Write(ushort address, byte value)
    {
        if (address is >= 0x9C00 and <= 0x9FFF)
        {
            _registers[address & 0x0F] = value;
            return;
        }

        if (TryMap(address, out var offset))
        {
            _image[offset] = value;
            _imageDirty = true;
        }
    }

    public byte[] GetImage() => _image.ToArray();
    public void ClearDirty() => _imageDirty = false;

    private bool TryMap(ushort address, out int offset)
    {
        // Bank select: registers 6+ pair per block (simplified from VICE CART_BLK_ADDR).
        int bankLo;
        int local;
        if (address is >= 0x0400 and <= 0x0FFF)
        {
            bankLo = _registers[6];
            local = address - 0x0400;
        }
        else if (address is >= 0x2000 and <= 0x3FFF)
        {
            bankLo = _registers[8];
            local = address - 0x2000;
        }
        else if (address is >= 0x4000 and <= 0x5FFF)
        {
            bankLo = _registers[10];
            local = address - 0x4000;
        }
        else if (address is >= 0x6000 and <= 0x7FFF)
        {
            bankLo = _registers[12];
            local = address - 0x6000;
        }
        else if (address is >= 0xA000 and <= 0xBFFF)
        {
            bankLo = _registers[14];
            local = address - 0xA000;
        }
        else
        {
            offset = 0;
            return false;
        }

        offset = ((bankLo & 0x7F) * 0x2000) + local;
        return offset >= 0 && offset < _image.Length;
    }
}
"}

{"file_path":"F:\GitHub\vice-sharp\src\ViceSharp.Core\Vic20\MegaCartCartridge.cs","content":"using ViceSharp.Abstractions;

namespace ViceSharp.Core.Vic20;

/// <summary>
/// VIC-20 Mega-Cart (VICE megacart.c) MVP: banked ROM + 8K NVRAM window.
/// </summary>
public sealed class MegaCartCartridge : IAddressSpace
{
    public const int LowRomSize = 0x100000;  // 1MB low
    public const int NvramSize = 0x2000;

    private readonly byte[] _rom;
    private readonly byte[] _nvram;
    private byte _bankLow = 0x7F;
    private byte _bankHigh = 0x7F;
    private bool _oe = true;
    private bool _nvramDirty;
    private bool _nvramEnabled;

    public MegaCartCartridge(ReadOnlySpan<byte> romImage, ReadOnlySpan<byte> nvram = default)
    {
        _rom = new byte[Math.Max(LowRomSize, romImage.Length)];
        if (!romImage.IsEmpty)
            romImage[..Math.Min(romImage.Length, _rom.Length)].CopyTo(_rom);
        _nvram = new byte[NvramSize];
        if (!nvram.IsEmpty)
            nvram[..Math.Min(nvram.Length, NvramSize)].CopyTo(_nvram);
        Id = new DeviceId(0x0C12);
        PowerUp();
    }

    public DeviceId Id { get; }
    public string Name => "Mega-Cart";
    public bool NvramDirty => _nvramDirty;
    public bool WriteBack { get; set; }
    public byte BankLow => _bankLow;
    public byte BankHigh => _bankHigh;

    public void PowerUp()
    {
        _bankLow = 0x7F;
        _bankHigh = 0x7F;
        _oe = true;
        _nvramEnabled = false;
    }

    public void Reset() => PowerUp();

    public void ApplyConfigPreset(string presetId)
    {
        switch (presetId.Trim().ToLowerInvariant())
        {
            case "default":
            case "start":
                PowerUp();
                break;
            case "bank0":
                _oe = true;
                _bankLow = 0x00;
                _bankHigh = 0x00;
                break;
            case "nvram":
                _nvramEnabled = true;
                break;
            default:
                throw new ArgumentException($"Unknown Mega-Cart preset '{presetId}'.", nameof(presetId));
        }
    }

    public bool HandlesAddress(ushort address)
        => address is (>= 0x9C00 and <= 0x9FFF)
            or (>= 0x9800 and <= 0x9BFF)
            or (>= 0x2000 and <= 0x7FFF)
            or (>= 0xA000 and <= 0xBFFF)
            or (>= 0x0400 and <= 0x0FFF);

    public byte Read(ushort address)
    {
        if (address is >= 0x9C00 and <= 0x9FFF)
            return ReadIo3(address);
        if (address is >= 0x9800 and <= 0x9BFF)
            return _bankLow; // IO2 mirrors bank low for tests
        if (_nvramEnabled && address is >= 0x0400 and <= 0x0FFF)
            return _nvram[address & 0x0FFF];
        if (TryMapRom(address, out var offset))
            return _rom[offset];
        return 0xFF;
    }

    public byte Peek(ushort address) => Read(address);

    public void Write(ushort address, byte value)
    {
        if (address is >= 0x9C00 and <= 0x9FFF)
        {
            WriteIo3(address, value);
            return;
        }

        if (address is >= 0x9800 and <= 0x9BFF)
        {
            _bankLow = value;
            return;
        }

        if (_nvramEnabled && address is >= 0x0400 and <= 0x0FFF)
        {
            _nvram[address & 0x0FFF] = value;
            _nvramDirty = true;
        }
    }

    public byte[] GetRomImage() => _rom.ToArray();
    public byte[] GetNvram() => _nvram.ToArray();
    public void ClearNvramDirty() => _nvramDirty = false;

    private byte ReadIo3(ushort address)
    {
        return (address & 1) == 0 ? _bankLow : _bankHigh;
    }

    private void WriteIo3(ushort address, byte value)
    {
        if ((address & 1) == 0)
            _bankLow = value;
        else
            _bankHigh = value;
        _oe = true;
        // bit7 of bank = RAM enable style (VICE ram_low_en)
        _nvramEnabled = (_bankLow & 0x80) != 0;
    }

    private bool TryMapRom(ushort address, out int offset)
    {
        var bank = _oe ? (_bankLow & 0x7F) : 0x7F;
        int local;
        if (address is >= 0x2000 and <= 0x3FFF)
            local = address - 0x2000;
        else if (address is >= 0x4000 and <= 0x5FFF)
            local = address - 0x4000 + 0x2000;
        else if (address is >= 0x6000 and <= 0x7FFF)
            local = address - 0x6000 + 0x4000;
        else if (address is >= 0xA000 and <= 0xBFFF)
            local = address - 0xA000 + 0x6000;
        else
        {
            offset = 0;
            return false;
        }

        offset = (bank * 0x2000) + (local & 0x1FFF);
        return offset >= 0 && offset < _rom.Length;
    }
}
"}

{"file_path":"F:\GitHub\vice-sharp\src\ViceSharp.Core\Vic20\Vic20ExpansionCartPort.cs","content":"using ViceSharp.Abstractions;
using ViceSharp.Core;

namespace ViceSharp.Core.Vic20;

/// <summary>
/// Runtime attach port for FE3 / Ultimem / Mega-Cart on a VIC-20 machine bus.
/// </summary>
public sealed class Vic20ExpansionCartPort : IVic20ExpansionCartPort, IDevice
{
    private readonly BasicBus _bus;
    private IAddressSpace? _attached;
    private Vic20ExpansionCartKind _kind;
    private string _configPresetId = "start";

    public Vic20ExpansionCartPort(BasicBus bus)
    {
        _bus = bus ?? throw new ArgumentNullException(nameof(bus));
        Id = new DeviceId(0x0C0F);
    }

    public DeviceId Id { get; }
    public string Name => "VIC-20 expansion cart port";
    public Vic20ExpansionCartKind AttachedKind => _kind;
    public bool WriteBack { get; set; }
    public string ConfigPresetId
    {
        get => _configPresetId;
        set => _configPresetId = value ?? "start";
    }

    public void Reset()
    {
        switch (_attached)
        {
            case FinalExpansion3Cartridge fe3:
                fe3.Reset();
                fe3.ApplyConfigPreset(_configPresetId);
                break;
            case UltimemCartridge um:
                um.Reset();
                um.ApplyConfigPreset(_configPresetId);
                break;
            case MegaCartCartridge mc:
                mc.Reset();
                mc.ApplyConfigPreset(_configPresetId);
                break;
        }
    }

    public void AttachFinalExpansion3(ReadOnlySpan<byte> flashImage)
    {
        Eject();
        var cart = new FinalExpansion3Cartridge(flashImage) { WriteBack = WriteBack };
        cart.ApplyConfigPreset(_configPresetId);
        _attached = cart;
        _kind = Vic20ExpansionCartKind.FinalExpansion3;
        _bus.RegisterDevice(cart);
    }

    public void AttachUltimem(ReadOnlySpan<byte> image)
    {
        Eject();
        var cart = new UltimemCartridge(image) { WriteBack = WriteBack };
        cart.ApplyConfigPreset(_configPresetId);
        _attached = cart;
        _kind = Vic20ExpansionCartKind.Ultimem;
        _bus.RegisterDevice(cart);
    }

    public void AttachMegaCart(ReadOnlySpan<byte> romImage, ReadOnlySpan<byte> nvram = default)
    {
        Eject();
        var cart = new MegaCartCartridge(romImage, nvram) { WriteBack = WriteBack };
        cart.ApplyConfigPreset(_configPresetId);
        _attached = cart;
        _kind = Vic20ExpansionCartKind.MegaCart;
        _bus.RegisterDevice(cart);
    }

    public void Eject()
    {
        if (_attached is null)
            return;
        _bus.UnregisterDevice(_attached);
        _attached = null;
        _kind = Vic20ExpansionCartKind.None;
    }

    public void ApplyConfigPreset(string presetId)
    {
        ConfigPresetId = presetId;
        switch (_attached)
        {
            case FinalExpansion3Cartridge fe3:
                fe3.ApplyConfigPreset(presetId);
                break;
            case UltimemCartridge um:
                um.ApplyConfigPreset(presetId);
                break;
            case MegaCartCartridge mc:
                mc.ApplyConfigPreset(presetId);
                break;
            default:
                break;
        }
    }

    public byte[]? FlushImage()
    {
        return _attached switch
        {
            FinalExpansion3Cartridge { WriteBack: true, FlashDirty: true } fe3 => fe3.GetFlashImage(),
            UltimemCartridge { WriteBack: true, ImageDirty: true } um => um.GetImage(),
            MegaCartCartridge { WriteBack: true } mc => mc.GetRomImage(),
            _ => null,
        };
    }

    public byte[]? FlushNvram()
    {
        if (_attached is MegaCartCartridge { NvramDirty: true } mc)
        {
            var data = mc.GetNvram();
            mc.ClearNvramDirty();
            return data;
        }

        return null;
    }

    public byte PeekIo(ushort address)
        => _attached?.Peek(address) ?? 0xFF;

    public void PokeIo(ushort address, byte value)
        => _attached?.Write(address, value);

    public bool TryReadMapped(ushort address, out byte value)
    {
        value = 0;
        if (_attached is null || !_attached.HandlesAddress(address))
            return false;
        value = _attached.Read(address);
        return true;
    }

    public bool TryWriteMapped(ushort address, byte value)
    {
        if (_attached is null || !_attached.HandlesAddress(address))
            return false;
        _attached.Write(address, value);
        return true;
    }
}
"}

{"file_path":"F:\GitHub\vice-sharp\src\ViceSharp.Core\Iec\FileSystemIecDevice.cs","content":"using System.Text;
using ViceSharp.Abstractions;

namespace ViceSharp.Core.Iec;

/// <summary>
/// Host-backed IEC filesystem device (VICE fsdevice / uIEC-style directory attach).
/// Available to any machine with an IEC bus; unit number is operator-selected.
/// </summary>
/// <remarks>
/// MVP: directory listing + sequential LOAD of a named file from a host path.
/// Not a full CBM DOS secondary-channel implementation.
/// </remarks>
public sealed class FileSystemIecDevice : IDevice
{
    private string _rootPath = string.Empty;

    public FileSystemIecDevice(int unitNumber = 9)
    {
        if (unitNumber is < 8 or > 11)
            throw new ArgumentOutOfRangeException(nameof(unitNumber), "IEC unit must be 8-11.");
        UnitNumber = unitNumber;
        Id = new DeviceId(0x0E00 + unitNumber);
    }

    public DeviceId Id { get; }
    public string Name => $"FileSystem IEC unit {UnitNumber}";
    public int UnitNumber { get; }
    public string RootPath => _rootPath;
    public bool IsAttached => !string.IsNullOrWhiteSpace(_rootPath) && Directory.Exists(_rootPath);

    public void Reset() { }

    /// <summary>Attach a host directory (PC path or SD mount). Empty detaches.</summary>
    public void AttachDirectory(string? path)
    {
        if (string.IsNullOrWhiteSpace(path))
        {
            _rootPath = string.Empty;
            return;
        }

        var full = Path.GetFullPath(path);
        if (!Directory.Exists(full))
            throw new DirectoryNotFoundException($"IEC filesystem root not found: '{full}'.");
        _rootPath = full;
    }

    public void Detach() => _rootPath = string.Empty;

    /// <summary>List file names in the attached directory (not recursive).</summary>
    public IReadOnlyList<string> ListFiles()
    {
        EnsureAttached();
        return Directory.GetFiles(_rootPath)
            .Select(Path.GetFileName)
            .Where(n => n is not null)
            .Cast<string>()
            .OrderBy(n => n, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    /// <summary>
    /// Sequential LOAD of a file by CBM-style name (case-insensitive match on host).
    /// Returns raw bytes; if the file starts with a 2-byte load address those are included.
    /// </summary>
    public byte[] LoadFile(string cbmName)
    {
        EnsureAttached();
        ArgumentException.ThrowIfNullOrWhiteSpace(cbmName);

        var name = cbmName.Trim().Trim('"');
        // Strip ,P,R style suffixes if present
        var comma = name.IndexOf(',');
        if (comma > 0)
            name = name[..comma];

        var match = Directory.GetFiles(_rootPath)
            .FirstOrDefault(f => string.Equals(Path.GetFileName(f), name, StringComparison.OrdinalIgnoreCase)
                || string.Equals(Path.GetFileNameWithoutExtension(f), name, StringComparison.OrdinalIgnoreCase));

        if (match is null)
            throw new FileNotFoundException($"File '{cbmName}' not found in IEC root '{_rootPath}'.");

        return File.ReadAllBytes(match);
    }

    /// <summary>Sequential SAVE of payload under <paramref name="cbmName"/> in the root.</summary>
    public void SaveFile(string cbmName, ReadOnlySpan<byte> data)
    {
        EnsureAttached();
        ArgumentException.ThrowIfNullOrWhiteSpace(cbmName);
        var safe = Path.GetFileName(cbmName.Trim().Trim('"'));
        if (string.IsNullOrWhiteSpace(safe))
            throw new ArgumentException("Invalid save name.", nameof(cbmName));
        var path = Path.Combine(_rootPath, safe);
        File.WriteAllBytes(path, data.ToArray());
    }

    /// <summary>Directory listing as PETSCII-ish text lines for UI/tests.</summary>
    public string FormatDirectoryListing()
    {
        var files = ListFiles();
        var sb = new StringBuilder();
        sb.AppendLine($"0 \"{_rootPath}\" 00 2A");
        foreach (var f in files)
        {
            var len = new FileInfo(Path.Combine(_rootPath, f)).Length;
            var blocks = Math.Max(1, (int)((len + 253) / 254));
            sb.AppendLine($"{blocks} \"{f}\" PRG");
        }

        sb.AppendLine("BLOCKS FREE.");
        return sb.ToString();
    }

    private void EnsureAttached()
    {
        if (!IsAttached)
            throw new InvalidOperationException("No host directory attached to the filesystem IEC device.");
    }
}
"}

