    public string PresetLabel
    {
        get
        {
            var id = MemorySpec;
            var label = SettingsOptionCatalog.FromVic20MemoryId(id);
            if (label != "Custom")
                return label;
            // Named presets that FormatMemorySpec returns as address tokens
            return id switch
            {
                "none" => "Unexpanded",
                "3k" => "3K",
                "8k" => "8K",
                "16k" => "16K",
                "24k" => "24K",
                "all" => "All",
                _ => "Custom",
            };
        }
    }

    public bool Blk0
    {
        get => (_blocks & Vic20RamBlocks.Blk0) != 0;
        set => SetBlock(Vic20RamBlocks.Blk0, value);
    }

    public bool Blk1
    {
        get => (_blocks & Vic20RamBlocks.Blk1) != 0;
        set => SetBlock(Vic20RamBlocks.Blk1, value);
    }

    public bool Blk2
    {
        get => (_blocks & Vic20RamBlocks.Blk2) != 0;
        set => SetBlock(Vic20RamBlocks.Blk2, value);
    }

    public bool Blk3
    {
        get => (_blocks & Vic20RamBlocks.Blk3) != 0;
        set => SetBlock(Vic20RamBlocks.Blk3, value);
    }

    public bool Blk5
    {
        get => (_blocks & Vic20RamBlocks.Blk5) != 0;
        set => SetBlock(Vic20RamBlocks.Blk5, value);
    }

    public void SetFromSpec(string? memorySpec)
    {
        if (!Vic20MemoryLayout.TryParseMemorySpec(memorySpec, out var blocks))
            blocks = Vic20RamBlocks.None;
        _blocks = blocks;
    }

    public void SetFromPresetLabel(string presetLabel)
    {
        var id = SettingsOptionCatalog.ToVic20MemoryId(presetLabel);
        if (id == "custom")
            return;
        SetFromSpec(id);
    }

    private void SetBlock(Vic20RamBlocks bit, bool enabled)
    {
        if (enabled)
            _blocks |= bit;
        else
            _blocks &= ~bit;
    }
