        Assert.Equal("fe3", session.Vic20ExpansionCartKind);

        var port = session.Machine.Devices.GetAll<IVic20ExpansionCartPort>().Single();
        Assert.Equal(Vic20ExpansionCartKind.FinalExpansion3, port.AttachedKind);
